        /// Gets the set flags as a container holding an array of bits.
        pub const fn bits(&self) -> FeatureBits {
            FeatureBits([self.features_wgpu.bits(), self.features_webgpu.bits()])
        }
        /// Returns self with no flags set.
        pub const fn empty() -> Self {
            Self {
                features_wgpu: FeaturesWGPU::empty(),
                features_webgpu: FeaturesWebGPU::empty(),
            }
        }
        /// Returns self with all flags set.
        pub const fn all() -> Self {
            Self {
                features_wgpu: FeaturesWGPU::all(),
                features_webgpu: FeaturesWebGPU::all(),
            }
        }
        /// Whether all the bits set in `other` are all set in `self`
        pub const fn contains(self, other: Self) -> bool {
            self.features_wgpu.contains(other.features_wgpu)
                && self.features_webgpu.contains(other.features_webgpu) && true
        }
        /// Returns whether any bit set in `self` matched any bit set in `other`.
        pub const fn intersects(self, other: Self) -> bool {
            self.features_wgpu.intersects(other.features_wgpu)
                || self.features_webgpu.intersects(other.features_webgpu) || false
        }
        /// Returns whether there is no flag set.
        pub const fn is_empty(self) -> bool {
            self.features_wgpu.is_empty() && self.features_webgpu.is_empty() && true
        }
        /// Returns whether the struct has all flags set.
        pub const fn is_all(self) -> bool {
            self.features_wgpu.is_all() && self.features_webgpu.is_all() && true
        }
        /// Bitwise or - `self | other`
        pub const fn union(self, other: Self) -> Self {
            Self {
                features_wgpu: self.features_wgpu.union(other.features_wgpu),
                features_webgpu: self.features_webgpu.union(other.features_webgpu),
            }
        }
        /// Bitwise and - `self & other`
        pub const fn intersection(self, other: Self) -> Self {
            Self {
                features_wgpu: self.features_wgpu.intersection(other.features_wgpu),
                features_webgpu: self.features_webgpu.intersection(other.features_webgpu),
            }
        }
        /// Bitwise and of the complement of other - `self & !other`
        pub const fn difference(self, other: Self) -> Self {
            Self {
                features_wgpu: self.features_wgpu.difference(other.features_wgpu),
                features_webgpu: self.features_webgpu.difference(other.features_webgpu),
            }
        }
        /// Bitwise xor - `self ^ other`
        pub const fn symmetric_difference(self, other: Self) -> Self {
            Self {
                features_wgpu: self
                    .features_wgpu
                    .symmetric_difference(other.features_wgpu),
                features_webgpu: self
                    .features_webgpu
                    .symmetric_difference(other.features_webgpu),
            }
        }
        /// Bitwise not - `!self`
        pub const fn complement(self) -> Self {
            Self {
                features_wgpu: self.features_wgpu.complement(),
                features_webgpu: self.features_webgpu.complement(),
            }
        }
        /// Calls [`Self::insert`] if `set` is true and otherwise calls [`Self::remove`].
        pub fn set(&mut self, other: Self, set: bool) {
            self.features_wgpu.set(other.features_wgpu, set);
            self.features_webgpu.set(other.features_webgpu, set);
        }
        /// Inserts specified flag(s) into self
        pub fn insert(&mut self, other: Self) {
            self.features_wgpu.insert(other.features_wgpu);
            self.features_webgpu.insert(other.features_webgpu);
        }
        /// Removes specified flag(s) from self
        pub fn remove(&mut self, other: Self) {
            self.features_wgpu.remove(other.features_wgpu);
            self.features_webgpu.remove(other.features_webgpu);
        }
        /// Toggles specified flag(s) in self
        pub fn toggle(&mut self, other: Self) {
            self.features_wgpu.toggle(other.features_wgpu);
            self.features_webgpu.toggle(other.features_webgpu);
        }
        /// Takes in [`FeatureBits`] and returns None if there are invalid bits or otherwise Self with
        /// those bits set
        pub const fn from_bits(bits: FeatureBits) -> Option<Self> {
            let [features_wgpu, features_webgpu] = bits.0;
            Some(Self {
                features_wgpu: match FeaturesWGPU::from_bits(features_wgpu) {
                    Some(some) => some,
                    None => return None,
                },
                features_webgpu: match FeaturesWebGPU::from_bits(features_webgpu) {
                    Some(some) => some,
                    None => return None,
                },
            })
        }
        /// Takes in [`FeatureBits`] and returns Self with only valid bits (all other bits removed)
        pub const fn from_bits_truncate(bits: FeatureBits) -> Self {
            let [features_wgpu, features_webgpu] = bits.0;
            Self {
                features_wgpu: FeaturesWGPU::from_bits_truncate(features_wgpu),
                features_webgpu: FeaturesWebGPU::from_bits_truncate(features_webgpu),
            }
        }
        /// Takes in [`FeatureBits`] and returns Self with all bits that were set without removing
        /// invalid bits
        pub const fn from_bits_retain(bits: FeatureBits) -> Self {
            let [features_wgpu, features_webgpu] = bits.0;
            Self {
                features_wgpu: FeaturesWGPU::from_bits_retain(features_wgpu),
                features_webgpu: FeaturesWebGPU::from_bits_retain(features_webgpu),
            }
        }
