        /// Combines the features from the internal flags into the entire features struct
        pub fn from_internal_flags(
            features_wgpu: FeaturesWGPU,
            features_webgpu: FeaturesWebGPU,
        ) -> Self {
            Self {
                features_wgpu,
                features_webgpu,
            }
        }
        /// Returns an iterator over the set flags.
        pub const fn iter(&self) -> bitflags::iter::Iter<Features> {
            bitflags::iter::Iter::__private_const_new(Features::FLAGS, *self, *self)
        }
        /// Returns an iterator over the set flags and their names.
        pub const fn iter_names(&self) -> bitflags::iter::IterNames<Features> {
            bitflags::iter::IterNames::__private_const_new(Features::FLAGS, *self, *self)
        }
